# The tests call exercise(files): each file is [path, text]; it picks a parser with
# ResultParser.for_file(path) and reports summary(text), or "LookupError" / "ValueError".
# It also probes the registration rules, restoring ResultParser.registry afterwards.

def _defining(make_class):
    saved = dict(ResultParser.registry)
    try:
        make_class()
        return "no error"
    except Exception as err:
        return type(err).__name__
    finally:
        ResultParser.registry.clear()
        ResultParser.registry.update(saved)


def _no_suffix():
    class NoSuffix(ResultParser):
        def parse(self, text):
            return []


def _duplicate():
    class AnotherJson(ResultParser, suffix=".json"):
        def parse(self, text):
            return []


def _contract():
    try:
        ResultParser()
        abstract = "no error"
    except TypeError:
        abstract = "TypeError"
    return {
        "base_is_abstract": abstract,
        "subclass_without_suffix": _defining(_no_suffix),
        "duplicate_suffix": _defining(_duplicate),
        "suffix_attribute": [JsonParser.suffix, JUnitStub.suffix],
        "lookup_via_subclass": type(TapParser.for_file("x.json")).__name__,
    }


def exercise(files: List[List[str]]) -> Dict[str, Any]:
    results = []
    for path, text in files:
        try:
            results.append(ResultParser.for_file(path).summary(text))
        except LookupError:
            results.append("LookupError")
        except ValueError:
            results.append("ValueError")
    return {"results": results, "suffixes": sorted(ResultParser.registry), "contract": _contract()}
